export async function getUserCoupons(
userId: string,
dependencies:
GetUserCouponsDependencies
) {
const user =
await dependencies.userRepository
.findById(userId);
if (!user) {
throw new Error(
"사용자를 찾을 수 없다."
);
}
return dependencies.couponRepository
.findByRecipientId(userId);
}
