RoomTrigger
using UnityEngine;
public class RoomTrigger : MonoBehaviour
{
public RoomController room;
bool _triggered = false; // 중복 방지
private void OnTriggerEnter(Collider other)
{
if (other.CompareTag("Player") && !_triggered)
{
room.StartRoom();
_triggered = true;
gameObject.SetActive(false); // 한 번만 실행
}
}
}
RoomController
IEnumerator RoomFlow()
{
// 1. 몬스터 생성
SpawnMonsters();
// 2. 몬스터 연출
if (_monsters.Count > 0 && _director != null)
{
Vector3 monsterOffset = new Vector3(0, 3, -5); // 카메라 위치 offset
for (int i = 0; i < _monsters.Count; i++)
{
if (_monsters[i] != null)
{
// 프리팹 카메라 생성 + Follow / LookAt 적용
CinemachineCamera cm = _director.ShowMonster(_monsters[i].transform, monsterOffset);
yield return new WaitForSeconds(2f);
// 연출 끝나면 카메라 제거
Destroy(cm.gameObject);
}
}
_director.ShowPlayer();
yield return new WaitForSeconds(0.5f);
}
// 3. 몬스터 전멸 대기
yield return StartCoroutine(WaitForClear());
// 4. 문 연출
if (_nextDoor != null && _director != null)
{
Vector3 doorOffset = new Vector3(0, 3, -5); // 문 카메라 offset
CinemachineCamera cmDoor = _director.ShowDoor(_nextDoor.transform, doorOffset);
yield return new WaitForSeconds(0.5f);
_nextDoor.DoorOpen();
yield return new WaitUntil(() => _nextDoor.IsOpened);
_director.ShowPlayer();
yield return new WaitForSeconds(3f);
Destroy(cmDoor.gameObject);
}
// 5. 다음 방
_manager?.EnterNextRoom();
}
Director
public class Director : MonoBehaviour
{
[Header("Camera Prefabs")]
[SerializeField] GameObject _cmMonsterPrefab;
[SerializeField] GameObject _cmDoorPrefab;
[SerializeField] CinemachineCamera _cmPlayer;
[Header("Cinemachine Brain")]
[SerializeField] CinemachineBrain _brain; // 씬에 있는 CM Brain 연결 (내가 계속 못고쳤던이유)
public void ShowPlayer() // 플레이어는 카메라 고정
{
GameObject player = GameObject.FindGameObjectWithTag("Player");
if (player != null)
SetCamera(_cmPlayer, player.transform);
}
// 몬스터 연출
public CinemachineCamera ShowMonster(Transform target, Vector3 offset)
{
if (target == null) return null;
GameObject camObj = Instantiate(_cmMonsterPrefab);
CinemachineCamera cm = camObj.GetComponent<CinemachineCamera>();
// 초기 위치 설정
cm.transform.position = target.position + offset;
cm.transform.LookAt(target);
cm.Follow = target;
cm.LookAt = target;
cm.Priority = 20;
_cmPlayer.Priority = 0;
return cm;
}
// 문 연출
public CinemachineCamera ShowDoor(Transform target, Vector3 offset)
{
if (target == null) return null;
GameObject camObj = Instantiate(_cmDoorPrefab);
CinemachineCamera cm = camObj.GetComponent<CinemachineCamera>();
cm.transform.position = target.position + offset;
cm.transform.LookAt(target);
cm.Follow = target;
cm.LookAt = target;
cm.Priority = 20;
_cmPlayer.Priority = 0;
return cm;
}
// 카메라가 어딜 타겟하는지 지정
void SetCamera(CinemachineCamera cam, Transform target)
{
if (cam == null || target == null) return;
cam.Follow = target;
cam.LookAt = target;
cam.Priority = 20;
_cmPlayer.Priority = 0;
}
}
